#include <vector>

using namespace std;

class Solution {
public:
    vector<int> gardenNoAdj(int n, vector<vector<int>>& paths) {
        vector<vector<int>> graph(n);
        for (auto& p : paths) {
            graph[p[0] - 1].push_back(p[1] - 1);
            graph[p[1] - 1].push_back(p[0] - 1);
        }

        vector<int> res(n, 0);
        for (int i = 0; i < n; ++i) {
            vector<bool> used(5, false);
            for (int nei : graph[i])
                used[res[nei]] = true;
            for (int c = 1; c <= 4; ++c) {
                if (!used[c]) {
                    res[i] = c;
                    break;
                }
            }
        }
        return res;
    }
};
